(window.CH2=window.CH2||[]).push({id:'maratib',n:22,t:'مراتب التلاوة',c:'#8338ec',p:'ص ١٨-١٩',
 intro:'للتلاوة ثلاث مراتب: التحقيق، والتدوير، والحدر.',
 secs:[{h:'التحقيق',b:'لغة: بلوغ حقيقة الشيء. واصطلاحاً: إخراج كل حرف من مخرجه، وإعطاؤه حقه ومستحقه، مع القراءة بتؤدة واطمئنان. ويستحب الأخذ به في مقام التعليم.'},
 {h:'التدوير',b:'مرتبة دائرة بين الحدر والتحقيق، أي وسط بينهما.'},
 {h:'الحدر',b:'لغة: الانحدار، من حدر يحدر إذا أسرع. واصطلاحاً: إدراج القراءة وسرعتها مع مراعاة أحكام التجويد.'},
 {h:'الترتيل',b:'أن يتبع بعض القرآن بعضاً على مكث وتفهم من غير عجلة، وهو الذي نزل به القرآن. ومن قرأ بأي مرتبة منها كان داخلاً في قوله تعالى ﴿وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا﴾. وذهب بعضهم إلى أنها أربعة: الترتيل والتحقيق والتدوير والحدر، والصواب أن الترتيل يشمل المراتب الثلاث.'}],
 ayat:[{k:'73:4',hw:'ورتل القرآن ترتيلا',lab:'الترتيل يشمل المراتب'}],
 cards:[['ما مراتب التلاوة؟','التحقيق، التدوير، الحدر.'],['ما التحقيق؟','إعطاء كل حرف حقه بتؤدة واطمئنان.'],['متى يستحب التحقيق؟','في مقام التعليم.'],['ما التدوير؟','وسط بين الحدر والتحقيق.'],['ما الحدر؟','الإسراع في القراءة مع مراعاة أحكام التجويد.'],['ما الترتيل؟','قراءة على مكث وتفهم من غير عجلة، ويشمل المراتب الثلاث.']],
 quiz:[['أبطأ المراتب:',['التحقيق','الحدر','التدوير'],0,'بتؤدة واطمئنان.'],['أسرع المراتب:',['الحدر','التدوير','التحقيق'],0,'مع مراعاة الأحكام.'],['المرتبة الوسطى:',['التدوير','الحدر'],0,'بين الحدر والتحقيق.']],
 vid:[{t:'مراتب التلاوة',narr:'للتلاوة ثلاث مراتب. التحقيق، وهو إعطاء كل حرف حقه بتؤدة واطمئنان، ويستحب في التعليم. والتدوير، وهو وسط بين الحدر والتحقيق. والحدر، وهو الإسراع في القراءة مع مراعاة أحكام التجويد.',items:['التحقيق ← بتؤدة','التدوير ← وسط','الحدر ← إسراع مع الأحكام']},
 {t:'الترتيل',narr:'والترتيل أن تتبع بعض القرآن بعضاً على مكث وتفهم من غير عجلة. ويشمل المراتب الثلاث، فمن قرأ بأي منها فهو داخل في قوله تعالى: ورتل القرآن ترتيلا.',items:['على مكث وتفهم','يشمل المراتب الثلاث']}]});
(window.CH2=window.CH2||[]).push({id:'lahn',n:23,t:'اللحن الجلي والخفي',c:'#ef476f',p:'ص ٢٠-٢١',
 intro:'اللحن في الاصطلاح: الميل عن الصواب في قراءة القرآن. وهو نوعان: جلي وخفي.',
 secs:[{h:'اللحن الجلي',b:'الخطأ الذي يطرأ على اللفظ فيخل بمبناه إخلالاً ظاهراً يشترك في معرفته علماء القراءة وعامة الناس، سواء أدى إلى فساد المعنى أم لا. مثاله: إبدال حرف بحرف، أو ضم التاء في ﴿أَنْعَمْتَ﴾، أو رفع المنصوب ونصب المرفوع، كقراءة ﴿وَنَادَىٰ نُوحٌ رَّبَّهُ﴾ برفع الرب ونصب نوح.'},
 {h:'حكم اللحن الجلي',b:'محرم، سواء أخل بالمعنى أم لا.'},
 {h:'اللحن الخفي',b:'الخطأ الذي يتعلق بكمال إتقان النطق، فلا يدركه إلا أهل الفن الحذاق ويخفى على العامة. مثاله: عدم ضبط المقادير في المدود والغنة والإدغام والإخفاء، والخطأ في تغليظ أو تفخيم اللامات أو الراءات. وسمي خفياً لأن أهل التجويد هم المختصون بمعرفته.'},
 {h:'حكم اللحن الخفي',b:'اختلف فيه علماء التجويد، والصواب أنه يعفى عنه لمن لا يستطيع الاحتراز منه. ويجب على من يستطيع تركه صناعة.'}],
 ayat:[{k:'1:7',hw:'أنعمت عليهم',lab:'ضم التاء لحن جلي'},{k:'11:45',hw:'ونادى نوح ربه',lab:'رفع المنصوب لحن جلي'}],
 cards:[['ما اللحن؟','الميل عن الصواب في قراءة القرآن.'],['ما اللحن الجلي؟','خطأ ظاهر في اللفظ يعرفه العلماء والعامة.'],['حكم الجلي؟','محرم.'],['ما اللحن الخفي؟','خطأ في كمال النطق لا يدركه إلا أهل الفن.'],['أمثلة الخفي؟','ترك ضبط المد والغنة والإدغام والإخفاء، والخطأ في تفخيم أو ترقيق اللام والراء.'],['حكم الخفي؟','يعفى عنه لمن لا يستطيع الاحتراز منه.']],
 quiz:[['ضم التاء في ﴿أَنْعَمْتَ﴾:',['لحن جلي','لحن خفي'],0,'خطأ ظاهر.'],['عدم ضبط الغنة:',['لحن خفي','لحن جلي'],0,'لا يدركه إلا أهل الفن.'],['حكم اللحن الجلي:',['محرم','مباح','مكروه'],0,'سواء أخل بالمعنى أم لا.']],
 vid:[{t:'اللحن الجلي',narr:'اللحن هو الميل عن الصواب في قراءة القرآن. وهو نوعان. اللحن الجلي، وهو خطأ ظاهر في اللفظ يعرفه العلماء والعامة، كإبدال حرف بحرف أو تغيير الحركة. وحكمه التحريم.',items:['خطأ ظاهر','إبدال حرف أو حركة','حكمه: حرام']},
 {t:'اللحن الخفي',narr:'واللحن الخفي خطأ يتعلق بكمال النطق، لا يدركه إلا أهل الفن، كعدم ضبط المد والغنة والإدغام والإخفاء. والصواب أنه يعفى عنه لمن لا يستطيع الاحتراز منه.',items:['يخفى على العامة','المد، الغنة، الإدغام، الإخفاء','يعفى لمن لم يستطع']}]});
(window.CH2=window.CH2||[]).push({id:'ithbat',n:14,t:'الإثبات والحذف',c:'#e63946',p:'ص ٩٨-١٠٤',
 intro:'إذا كان آخر الكلمة الموقوف عليها حرف مد، فالوقف عليه يكون بإثباته أو بحذفه حسب رسم المصحف العثماني. الباب ثلاثة أنواع: الألف، والواو، والياء.',
 secs:[
 {h:'القاعدة العامة',b:'حرف المد الذي يثبت في الرسم العثماني يثبت عند الوقف. والذي حُذف من الرسم يُحذف عند الوقف. فإثبات حرف المد وقفاً تابع لإثباته في المصاحف، وحذفه وقفاً تابع لحذفه فيها.'},
 {h:'النوع الأول: الألف',b:'<b class=g>تثبت الألف في الوقف</b> إذا كانت ثابتة في الرسم، سواء كانت ثابتة وصلاً ووقفاً بأن كان ما بعدها متحركاً، مثل ﴿رَبَّنَا ظَلَمْنَآ أَنفُسَنَا﴾، أم محذوفة وصلاً لالتقاء الساكنين، مثل ﴿وَقَالَا ٱلْحَمْدُ لِلَّهِ﴾ و﴿يَـٰٓأَيُّهَا ٱلنَّاسُ﴾.'},
 {h:'ألفاظ محذوفة وصلاً ومثبتة وقفاً',b:'<b class=r>﴿أَنَا﴾</b> حيث وقع، سواء كان بعده همزة مثل ﴿أَنَا۠ أُنَبِّئُكُم﴾ أو لم يكن مثل ﴿وَأَنَا۠ بِهِۦ زَعِيمٌ﴾. وتثبت الألف وقفاً في: ﴿ٱلظُّنُونَا۠﴾ و﴿ٱلرَّسُولَا۠﴾ و﴿ٱلسَّبِيلَا۠﴾ في الأحزاب، و﴿لَّـٰكِنَّا۠﴾ في الكهف، و﴿قَوَارِيرَا۠﴾ الأولى في الإنسان.'},
 {h:'مستثنيات من الإثبات (تحذف وقفاً)',b:'١) ﴿قَوَارِيرَا۟﴾ الثانية في الإنسان: ألفها محذوفة وصلاً ووقفاً.<br>٢) ﴿ثَمُودَا۟﴾: تحذف وصلاً ووقفاً في أربعة مواضع.<br>٣) ﴿سَلَـٰسِلَا۟﴾ في الإنسان: لحفص حذفها قولاً واحداً، وله إثباتها وحذفها.<br>٤) الألف المحذوفة رسماً تحذف وقفاً تبعاً للرسم، مثل ﴿أَيُّهَ ٱلْمُؤْمِنُونَ﴾ في النور.'},
 {h:'ما يلحق بالألف المحذوفة',b:'الألف في ﴿وَلَيَكُونَا﴾ في يوسف، و﴿لَنَسْفَعًا﴾ في العلق، والمنون المنصوب مثل ﴿عَلِيمًا حَكِيمًا﴾ لأن الألف بدل من التنوين، و﴿إِذًا﴾. وأصل الألف في المواضع الأولى نون التوكيد الخفيفة، وفي المثالين الأخيرين مبدلة من التنوين.'},
 {h:'النوع الثاني: الواو',b:'تثبت الواو وقفاً إذا ثبتت في الرسم، سواء كان بعدها متحرك مثل ﴿وَٱسْتَعِينُواْ بِٱلصَّبْرِ﴾ أم محذوفة وصلاً وبعدها ساكن مثل ﴿وَقَالُواْ ٱلْحَمْدُ﴾.<br>وحذفت الواو رسماً ولفظاً وصلاً ووقفاً من أربعة أفعال: ﴿وَيَدْعُ ٱلْإِنسَـٰنُ﴾، ﴿وَيَمْحُ ٱللَّهُ ٱلْبَـٰطِلَ﴾، ﴿يَوْمَ يَدْعُ ٱلدَّاعِ﴾، ﴿سَنَدْعُ ٱلزَّبَانِيَةَ﴾. ويلحق بها ﴿وَصَـٰلِحُ ٱلْمُؤْمِنِينَ﴾ في التحريم.'},
 {h:'النوع الثالث: الياء',b:'تثبت الياء وقفاً إذا ثبتت رسماً، وصلاً كانت أو وقفاً. وإذا حذفت وصلاً لالتقاء الساكنين مثل ﴿يُؤْتِ ٱلْحِكْمَةَ﴾ ثبتت لو وقف القارئ.<br>وتحذف الياء وقفاً إذا حذفت رسماً مثل ﴿وَلْيَتَّقِ﴾ و﴿يَـٰعِبَادِ﴾ و﴿وَءَاتِ ذَا ٱلْقُرْبَىٰ﴾.'},
 {h:'مواضع الياء المحذوفة بعد ساكن',b:'من المواضع التي وقع فيها ياء محذوفة بعد ساكن سبعة عشر موضعاً، منها ﴿وَسَوْفَ يُؤْتِ ٱللَّهُ﴾ ﴿فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ﴾ ﴿بِٱلْوَادِ ٱلْمُقَدَّسِ﴾ ﴿لَهَادِ ٱلَّذِينَ﴾ ﴿ٱلْجَوَارِ ٱلْكُنَّسِ﴾.'},
 {h:'الكلمة المستثناة',b:'﴿فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ﴾ في النمل: يجوز فيها الوقف بالإثبات والحذف لحفص. وأما وصلاً فليس لحفص إلا إثباتها مفتوحة.'}],
 ayat:[{k:'7:23',hw:'ربنا ظلمنا',lab:'ألف ثابتة وصلاً ووقفاً'},{k:'33:66',hw:'الرسولا',lab:'تثبت الألف وقفاً'},{k:'18:38',hw:'لكنا',lab:'تثبت الألف وقفاً'},{k:'27:36',hw:'فما آتاني الله',lab:'إثبات الياء وحذفها وقفاً'}],
 cards:[['ما الأنواع الثلاثة في الباب؟','الألف، الواو، الياء.'],['ما القاعدة العامة؟','إثبات حرف المد أو حذفه وقفاً تابع للرسم العثماني.'],['ما اللفظ الذي تثبت ألفه وقفاً وتحذف وصلاً؟','﴿أَنَا﴾.'],['ما الكلمات التي تثبت ألفها وقفاً في الأحزاب؟','الظنونا، الرسولا، السبيلا.'],['ما الألف المحذوفة وصلاً ووقفاً في الإنسان؟','﴿قَوَارِيرَا۟﴾ الثانية.'],['ما الأفعال التي حذفت منها الواو؟','يدع الإنسان، يمح الله، يدع الداع، سندع الزبانية.'],['كيف تقف على ﴿وَلْيَتَّقِ﴾؟','بحذف الياء لأنها محذوفة رسماً.'],['ما الكلمة التي يجوز فيها الإثبات والحذف وقفاً؟','﴿فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ﴾ في النمل.']],
 quiz:[['حذف حرف المد وقفاً يتبع:',['الرسم العثماني','اللغة فقط','اختيار القارئ'],0,'يتبع الرسم.'],['﴿أَنَا﴾ عند الوقف:',['تحذف ألفها','تثبت ألفها'],1,'تثبت الألف وقفاً.'],['﴿ٱلرَّسُولَا۠﴾ في الأحزاب وقفاً:',['تحذف','تثبت'],1,'تثبت الألف وقفاً.'],['﴿ثَمُودَا۟﴾ وقفاً:',['تثبت','تحذف'],1,'محذوفة وصلاً ووقفاً.'],['﴿وَيَدْعُ ٱلْإِنسَـٰنُ﴾ الواو:',['تثبت','تحذف'],1,'حذفت رسماً ولفظاً.']],
 vid:[{t:'الإثبات والحذف',narr:'إذا كان آخر الكلمة الموقوف عليها حرف مد، فإن إثباته أو حذفه عند الوقف تابع للرسم العثماني. والباب ثلاثة أنواع: الألف والواو والياء.',items:['تابع للرسم العثماني','الألف','الواو','الياء']},
 {t:'الألف',narr:'تثبت الألف وقفاً إذا ثبتت في الرسم. وتثبت وقفاً في كلمة أنا، والظنونا والرسولا والسبيلا في الأحزاب، ولكنا في الكهف. وتحذف في ثمودا، وفي قواريرا الثانية.',items:['تثبت: أنا، الظنونا، الرسولا، السبيلا','تحذف: ثمودا، قواريرا الثانية']},
 {t:'الواو والياء',narr:'والواو تحذف من أربعة أفعال: ويدع الإنسان، ويمح الله، ويوم يدع الداع، وسندع الزبانية. والياء تثبت إذا ثبتت في الرسم، وتحذف إذا حذفت رسماً، مثل: وليتق، ويا عباد.',items:['حذف الواو: يدع، يمح، يدع، سندع','الياء: تابعة للرسم']}]});
(window.CH2=window.CH2||[]).push({id:'maqtu',n:15,t:'المقطوع والموصول',c:'#2b9348',p:'ص ١٠٥-١٢٣',
 intro:'هذا الباب يعتني برسم الكلمات في المصحف العثماني: أيها كُتب مفصولاً عن غيره (مقطوع)، وأيها كُتب متصلاً (موصول). فائدته معرفة كيف يقف القارئ على الكلمة عند الامتحان أو التعليم أو ضيق النفس.',
 secs:[
 {h:'القاعدة',b:'<b class=g>الكلمة المفصولة</b> عما بعدها يجوز الوقف عليها عند التعلم أو الامتحان أو ضيق النفس. <b class=g>والكلمة الموصولة</b> لا يجوز الوقف على الأولى منهما، بل على الثانية. وإذا كانت الكلمة مختلفاً في قطعها ووصلها جاز الوقف عليها نظراً إلى القطع والوصل، ووجب الوقف على الكلمة الأخيرة منهما إذا اقتضى الأمر ذلك. والقطع هو الأصل، والوصل فرع عنه.'},
 {h:'١ أن + لا',b:'مقطوعة باتفاق في عشرة مواضع، مثل ﴿أَن لَّآ أَقُولَ عَلَى ٱللَّهِ﴾ و﴿أَن لَّا يَقُولُواْ﴾ و﴿أَن لَّا مَلْجَأَ﴾. وموضع واحد مختلف: ﴿أَن لَّآ إِلَـٰهَ إِلَّآ أَنتَ سُبْحَـٰنَكَ﴾ في الأنبياء، والعمل على الوصل. وما سوى ذلك موصول، مثل ﴿أَلَّا تَعْبُدُوٓاْ إِلَّا ٱللَّهَ﴾.'},
 {h:'٢ أن + لم، ٣ أن + لو',b:'﴿أَن لَّمْ﴾ مقطوعة في القرآن كله: ﴿ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ﴾. و﴿أَن لَّوْ﴾ مقطوعة في أربعة مواضع: ﴿أَن لَّوْ نَشَآءُ أَصَبْنَـٰهُم﴾ ﴿أَن لَّوْ يَشَآءُ ٱللَّهُ﴾ ﴿أَن لَّوْ كَانُواْ يَعْلَمُونَ﴾ ﴿وَأَلَّوِ ٱسْتَقَـٰمُواْ﴾ (والأخيرة موصولة في الجن).'},
 {h:'٤ أن + لن',b:'موصولة باتفاق في موضعين: ﴿أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا﴾ و﴿أَلَّن نَّجْمَعَ عِظَامَهُ﴾. ومختلف فيها في موضع (﴿أَن لَّن تُحْصُوهُ﴾ في المزمل) والمشهور القطع. وما عدا ذلك مقطوع، مثل ﴿أَن لَّن يَنقَلِبَ ٱلرَّسُولُ﴾.'},
 {h:'٥ إن + لم، ٦ إن + ما، ٧ إن + لا',b:'﴿إِن لَّمْ﴾ موصولة في موضع واحد ﴿فَإِلَّمْ يَسْتَجِيبُواْ لَكُمْ﴾ في هود، وما عداه مقطوع مثل ﴿فَإِن لَّمْ تَفْعَلُواْ﴾.<br>﴿إِن مَّا﴾ مقطوعة في موضع واحد ﴿وَإِن مَّا نُرِيَنَّكَ﴾ في الرعد، وموصولة فيما عداه مثل ﴿فَإِمَّا تَرَيِنَّ﴾.<br>﴿إِلَّا﴾ (إن لا) موصولة في جميع القرآن مثل ﴿إِلَّا تَفْعَلُوهُ﴾ ﴿إِلَّا تَنصُرُوهُ﴾.'},
 {h:'٨ أم + من',b:'مقطوعة (أم من) في أربعة مواضع بلا خلاف: ﴿أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا﴾ ﴿أَم مَّنْ أَسَّسَ﴾ ﴿أَم مَّنْ خَلَقْنَآ﴾ ﴿أَم مَّن يَأْتِىٓ ءَامِنًا﴾. وما عدا ذلك موصول مثل ﴿أَمَّن يُجِيبُ ٱلْمُضْطَرَّ﴾ و﴿أَمَّن لَّا يَهِدِّىٓ﴾. وأما ﴿أَمَّا﴾ فموصولة دائماً لأن أصلها (أم) مدغمة في (ما).'},
 {h:'٩ أن + ما، ١٠ إن + ما (مشددة)',b:'﴿وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ﴾ مقطوعة في موضعين (الحج ولقمان). و﴿وَٱعْلَمُوٓاْ أَنَّمَا غَنِمْتُم﴾ مختلف فيه والعمل الوصل. والباقي موصول.<br>﴿إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ﴾ مقطوعة في الأنعام، وفي النحل خلاف والوصل أقوى. وما عدا ذلك موصول مثل ﴿إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ﴾.'},
 {h:'١١ أين + ما، ١٢ عن + ما، ١٣ عن + من',b:'﴿أَيْنَمَا﴾ موصولة في البقرة والنحل (﴿يُوَجِّههُّ﴾)، والخلاف في ثلاثة مواضع: والعمل على الوصل في النساء والأحزاب والقطع في الشعراء. وما عداها مقطوع مثل ﴿أَيْنَ مَا كُنتُمْ تَدْعُونَ﴾.<br>﴿عَن مَّا﴾ مقطوعة في موضع واحد ﴿فَلَمَّا عَتَوْاْ عَن مَّا نُهُواْ عَنْهُ﴾ في الأعراف، وموصولة فيما سواه مثل ﴿عَمَّا يَقُولُونَ﴾.<br>﴿عَن مَّن﴾ مقطوعة في موضعين: ﴿عَن مَّن يَشَآءُ﴾ في النور و﴿عَن مَّن تَوَلَّىٰ﴾ في النجم.'},
 {h:'١٤ حيث + ما، ١٥ من + ما',b:'﴿حَيْثُ مَا﴾ مقطوعة في موضعين في البقرة: ﴿وَحَيْثُ مَا كُنتُمْ فَوَلُّواْ﴾.<br>﴿فَمِن مَّا مَلَكَتْ أَيْمَـٰنُكُم﴾ مقطوعة في النساء. وفي الروم والمنافقون خلاف والعمل القطع (﴿مِّن مَّا مَلَكَتْ﴾، ﴿مِن مَّا رَزَقْنَـٰكُم﴾). والباقي موصول مثل ﴿وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ﴾.'},
 {h:'١٦ بئس + ما، ١٧ كل + ما',b:'﴿بِئْسَمَا ٱشْتَرَوْاْ بِهِۦٓ أَنفُسَهُمْ﴾ موصولة في البقرة. وفيها خلاف في موضعين (البقرة ﴿بِئْسَمَا يَأْمُرُكُم﴾ والأعراف ﴿بِئْسَمَا خَلَفْتُمُونِى﴾) والعمل الوصل. ومقطوعة في ستة مواضع مثل ﴿وَلَبِئْسَ مَا شَرَوْاْ بِهِۦٓ أَنفُسَهُمْ﴾ ﴿فَبِئْسَ مَا يَشْتَرُونَ﴾ ﴿لَبِئْسَ مَا كَانُواْ يَعْمَلُونَ﴾.<br>﴿كُلَّ مَا﴾: مقطوعة في إبراهيم ﴿مِّن كُلِّ مَا سَأَلْتُمُوهُ﴾. ومختلف في أربعة مواضع (النساء، الأعراف، المؤمنون، الملك) والعمل القطع في النساء والمؤمنين، والوصل في الأعراف والملك. والباقي موصول مثل ﴿كُلَّمَا رُزِقُواْ﴾.'},
 {h:'١٨ كي + لا، ١٩ في + ما',b:'﴿لِكَيْلَا﴾ موصولة في الحج والأحزاب والحديد: ﴿لِكَيْلَا يَعْلَمَ﴾ ﴿لِكَيْلَا يَكُونَ﴾ ﴿لِكَيْلَا تَأْسَوْاْ﴾. وفي آل عمران ﴿لِكَيْلَا تَحْزَنُواْ﴾ خلاف والعمل الوصل. ومقطوعة (كي لا) في ثلاثة مواضع: في النحل ﴿لِكَيْ لَا يَعْلَمَ﴾، وفي الأحزاب ﴿لِكَيْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ﴾، وفي الحشر ﴿كَىْ لَا يَكُونَ دُولَةً﴾.<br>﴿فِى مَا﴾ مقطوعة في أحد عشر موضعاً مثل ﴿فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ﴾ ﴿فِى مَا ءَاتَىٰكُمْ﴾ ﴿فِى مَا أُوحِىَ﴾. وموصولة في سواها مثل ﴿فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ﴾. وإذا دخلت (في) على (ما) الاستفهامية المحذوفة الألف فهي موصولة مثل ﴿فِيمَ كُنتُمْ﴾.'},
 {h:'٢٠ يوم + هم، ٢١ لام الجر',b:'﴿يَوْمَ هُم﴾ مقطوعة في موضعين: ﴿يَوْمَ هُم بَـٰرِزُونَ﴾ ﴿يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ﴾، لأن (هم) في موضع رفع مبتدأ. وموصولة فيما عداهما مثل ﴿يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ﴾.<br>لام الجر مع ما بعدها مقطوعة في أربعة مواضع: ﴿فَمَالِ هَـٰٓؤُلَآءِ ٱلْقَوْمِ﴾ ﴿مَالِ هَـٰذَا ٱلْكِتَـٰبِ﴾ ﴿مَالِ هَـٰذَا ٱلرَّسُولِ﴾ ﴿فَمَالِ ٱلَّذِينَ كَفَرُواْ﴾. ويجوز الوقف على (ما) أو على (اللام)، لكن يبدأ القارئ بـ﴿مَالِ﴾.'},
 {h:'٢٢ ولات حين مناص، ٢٣ كالوهم ووزنوهم، ٢٥ ابن أم',b:'﴿وَلَاتَ حِينَ مَنَاصٍ﴾ في ص: التاء مفصولة عن (حين) على الصحيح المعمول به. وعلى هذا يصح الوقف على (ولات) عند التعليم أو الامتحان أو ضيق النفس، لكن لا يصح الوقف عليها اختياراً.<br>﴿كَالُوهُمْ﴾ و﴿وَزَنُوهُمْ﴾ في المطففين: موصولتان حكماً، فلا يجوز الوقف على (كالوا) ولا على (وزنوا).<br>﴿قَالَ ٱبْنَ أُمَّ﴾ في الأعراف: مقطوعة، ويجوز الوقف على (ابن) بالباء الموحدة. وأما ﴿يَبْنَؤُمَّ﴾ في طه فموصولة.'},
 {h:'ما اتفقت المصاحف على وصله',b:'﴿يَوْمَئِذٍ﴾ و﴿حِينَئِذٍ﴾ و﴿وَيْكَأَنَّ﴾، وكذلك (ال) التعريف، و(يا) النداء، و(ها) التنبيه، مثل ﴿ٱلرَّحِيمِ﴾ ﴿يَـٰٓـَٔادَمُ﴾ ﴿هَـٰذَا﴾ ﴿هَـٰٓؤُلَآءِ﴾. وكذلك ﴿نِعِمَّا﴾ و﴿كَأَنَّمَا﴾ و﴿مَهْمَا﴾ و﴿رُّبَمَا﴾. وفواتح السور المركبة لا يوقف إلا على نهايتها، مثل ﴿حمۤ ﴿١﴾ عۤسۤقۤ﴾ فتكتب مقطوعة.'}],
 ayat:[{k:'7:105',hw:'أن لا أقول',lab:'أن + لا: مقطوعة'},{k:'4:109',hw:'أم من يكون',lab:'أم + من: مقطوعة'},{k:'14:34',hw:'من كل ما',lab:'كل + ما: مقطوعة'},{k:'78:40',hw:'',lab:''}].slice(0,3),
 cards:[['ما المقطوع؟','الكلمة المفصولة في الرسم عما بعدها.'],['ما الموصول؟','الكلمة المتصلة في الرسم بما بعدها.'],['ما الأصل: القطع أم الوصل؟','القطع هو الأصل، والوصل فرع.'],['متى يجوز الوقف على كلمة مقطوعة؟','عند التعلم أو الامتحان أو ضيق النفس.'],['أن + لا: مقطوعة في كم موضع؟','عشرة مواضع باتفاق.'],['أن + لم؟','مقطوعة في القرآن كله.'],['إن + لا؟','موصولة في القرآن كله (إلا).'],['أم + من؟','مقطوعة في أربعة مواضع.'],['عن + ما؟','مقطوعة في موضع واحد في الأعراف.'],['في + ما؟','مقطوعة في أحد عشر موضعاً.'],['يوم + هم؟','مقطوعة في موضعين: غافر والذاريات.'],['لام الجر في «مال»؟','مقطوعة في أربعة مواضع.'],['ما الكلمات الموصولة باتفاق؟','يومئذ، حينئذ، ويكأن، ونعما، وكأنما، ومهما، وربما.']],
 quiz:[['الأصل في الكلمات القرآنية:',['القطع','الوصل'],0,'القطع هو الأصل والوصل فرع.'],['﴿أَن لَّمْ﴾ في القرآن:',['مقطوعة دائماً','موصولة دائماً'],0,'مقطوعة في القرآن كله.'],['﴿إِلَّا تَفْعَلُوهُ﴾ (إن لا):',['مقطوعة','موصولة'],1,'موصولة في القرآن كله.'],['﴿يَوْمَئِذٍ﴾:',['مقطوعة','موصولة'],1,'موصولة باتفاق.'],['﴿أَم مَّنْ أَسَّسَ﴾:',['مقطوعة','موصولة'],0,'أم من مقطوعة في أربعة مواضع.'],['﴿مَالِ هَـٰذَا ٱلْكِتَـٰبِ﴾ يجوز الوقف على:',['مال بتمامها','ما أو اللام عند الضرورة والتعلم'],1,'يجوز عند الامتحان أو ضيق النفس، ويبتدئ بمال.']],
 vid:[{t:'المقطوع والموصول',narr:'هذا الباب يتعلق برسم الكلمات في المصحف العثماني. فالمقطوع هو الكلمة المكتوبة منفصلة عما بعدها. والموصول هو المكتوبة متصلة. والأصل هو القطع، والوصل فرع عنه.',items:['المقطوع: مفصول في الرسم','الموصول: متصل في الرسم','الأصل: القطع']},
 {t:'متى نستفيد منه؟',narr:'تستفيد من هذا الباب إذا وقفت للتعلم، أو للامتحان، أو لضيق النفس. فيجوز الوقف على الكلمة المقطوعة. أما الموصولة فلا يوقف على الأولى منهما.',items:['عند التعلم أو الامتحان','أو عند ضيق النفس','الموصولة: لا يوقف على الأولى']},
 {t:'أمثلة مقطوعة',narr:'من الأمثلة: أن لا، عشرة مواضع بالاتفاق. وأن لم، في القرآن كله. وأم من، في أربعة مواضع. وعن ما، في موضع واحد في الأعراف. وفي ما، في أحد عشر موضعاً. ويوم هم، في موضعين.',items:['أن لا: ١٠ مواضع','أن لم: كل القرآن','أم من: ٤ مواضع','في ما: ١١ موضعاً']},
 {t:'ما اتفق على وصله',narr:'ومما اتفقت المصاحف على وصله: يومئذ، وحينئذ، وويكأن، ونعما، وكأنما، ومهما، وربما. وكذلك ال التعريف، ويا النداء، وها التنبيه.',items:['يومئذ، حينئذ','ويكأن، ونعما','كأنما، مهما، ربما']}]});
(window.CH2=window.CH2||[]).push({id:'mubt',n:19,t:'تحذير من مبتدعات في التلاوة',c:'#d62828',p:'ص ١٤٢-١٤٣',
 intro:'للقرآن كيفية مخصوصة في التلاوة يجب الالتزام بها، دون زيادة على الحد الوارد ولا نقص منه.',
 secs:[
 {h:'الأصل',b:'كيفية التلاوة تتجلى في إعطاء كل حرف حقه ومستحقه، من غير تكلف، مع التيسير والتسهيل، كما في قوله تعالى ﴿وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا﴾.'},
 {h:'أمثلة المبتدعات',b:'• المبالغة في الإخفاء حتى يصير شبيهاً بالمد، أو جعل النون الساكنة والتنوين إظهاراً بغنة.<br>• ضم الشفتين عند النطق بالحروف المفخمة المفتوحة مبالغة في التفخيم.<br>• خلط المرققة بشيء من الإمالة ظناً أنه مبالغة في الترقيق.<br>• إعطاء الحرف صفة مجاوره، قوية أو ضعيفة.<br>• الإفراط في المد عن مقداره.<br>• إشباع حركة ما قبل النون الساكنة بعد حرف الإخفاء، مثل ﴿كُنتُمْ﴾، فيتولد حرف مد، وهذا خطأ.<br>• إشباع حركة الميم والنون المشددتين في ﴿إِمَّا﴾ و﴿إِنَّ﴾.<br>• تخفيف الحرف المثقل، مثل ﴿ٱلْحَجَّ﴾ وعكسه ﴿بِعَادٍ﴾، وخاصة عند الوقف.'}],
 ayat:[{k:'73:4',hw:'ورتل القرآن ترتيلا',lab:'الأصل في التلاوة'}],
 cards:[['ما حكم الزيادة على الحد الوارد في التلاوة؟','لا تجوز، وكذلك النقص عنه.'],['ما الأصل في التلاوة؟','إعطاء كل حرف حقه من غير تكلف.'],['مثال مبتدع في الإخفاء؟','المبالغة حتى يشبه المد أو يصير إظهاراً بغنة.'],['حكم إشباع الحركة قبل حرف الإخفاء؟','خطأ لأنه يولد حرف مد.'],['حكم تخفيف الحرف المثقل؟','خطأ، مثل ﴿الحج﴾.']],
 quiz:[['من المبتدعات:',['إشباع الضمة فتولد واو','إخراج الحرف من مخرجه'],0,'يتولد حرف مد.'],['﴿ٱلْحَجَّ﴾ يجب أن:',['يشدد','يخفف'],0,'تخفيفه خطأ.']],
 vid:[{t:'التحذير من المبتدعات',narr:'للقرآن كيفية مخصوصة في التلاوة، لا نزيد عليها ولا ننقص منها. فنعطي كل حرف حقه من غير تكلف.',items:['لا زيادة','لا نقص','بلا تكلف']},
 {t:'أمثلة',narr:'ومن الأخطاء: المبالغة في الإخفاء، وضم الشفتين عند التفخيم، والإفراط في المد، وتخفيف الحرف المشدد كما في الحج.',items:['مبالغة الإخفاء','ضم الشفتين','إفراط المد','تخفيف المشدد']}]});
(window.CH2=window.CH2||[]).push({id:'shat',n:18,t:'ما يراعى لحفص من الشاطبية',c:'#e76f51',p:'ص ١٤٠-١٤١',
 intro:'هناك أحكام تراعى لمن يقرأ برواية حفص عن عاصم من طريق الشاطبية، وهي أمور ينبغي أخذها بالتلقي عن المشايخ المتقنين.',
 secs:[
 {h:'١. تسهيل الهمزة الثانية',b:'النطق بالهمزة الثانية المفتوحة مسهلة بين الهمزة والألف في ﴿ءَأَعْجَمِىٌّ وَعَرَبِىٌّ﴾ في فصلت. ولا يحكم النطق به إلا المشافهة والتلقي.'},
 {h:'٢. الإمالة',b:'إمالة الراء والألف بعدها في ﴿مَجْر۪ىٰهَا﴾ من قوله تعالى ﴿بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَا﴾ في هود. وهي إمالة محضة، ولم يمل حفص في القرآن إلا هذه الكلمة، ومعناها تقريب الفتحة من الكسرة والألف من الياء من غير قلب خالص ولا مبالغة.'},
 {h:'٣. السين والصاد',b:'﴿وَيَبْصُۜطُ﴾ في البقرة و﴿بَصْۜطَةً﴾ في الأعراف: النطق بالسين فقط.<br>﴿بِمُصَيْطِرٍ﴾ في الغاشية: النطق بالصاد فقط.<br>﴿ٱلْمُصَيْطِرُونَ﴾ في الطور: بالصاد والسين، والمقدم في الأداء الصاد.'},
 {h:'٤. فتح الضاد وضمها',b:'في ﴿ضَعْفٍ﴾ و﴿ضَعْفًا﴾ في المواضع الثلاثة من آية الروم ﴿ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِن بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِن بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً﴾: الفتح روايته عن عاصم وهو المقدم في الأداء، والضم اختياره مما رواه عن غير عاصم.'}],
 ayat:[{k:'11:41',hw:'مجراها',lab:'إمالة محضة لحفص'},{k:'30:54',hw:'ضعف',lab:'الفتح المقدم والضم جائز'},{k:'88:22',hw:'بمصيطر',lab:'بالصاد'}],
 cards:[['كيف تنطق ﴿ءَأَعْجَمِىٌّ﴾ في فصلت؟','الهمزة الثانية مسهلة بين الهمزة والألف.'],['ما الكلمة التي أمالها حفص؟','مجراها في هود.'],['كيف ينطق ﴿يَبْصُطُ﴾ و﴿بَصْطَةً﴾؟','بالسين.'],['كيف ينطق ﴿بِمُصَيْطِرٍ﴾؟','بالصاد.'],['وجها ﴿ٱلْمُصَيْطِرُونَ﴾؟','الصاد والسين، والمقدم الصاد.'],['المقدم في ضعف في الروم؟','الفتح.']],
 quiz:[['الكلمة التي فيها إمالة لحفص:',['مجراها','مرساها','الصلاة'],0,'إمالة ﴿مَجْر۪ىٰهَا﴾ في هود فقط.'],['﴿بَصْطَةً﴾ تنطق:',['بالسين','بالصاد'],0,'بالسين.'],['المقدم في ﴿ضَعْفٍ﴾ في الروم:',['الفتح','الضم'],0,'الفتح روايته عن عاصم.']],
 vid:[{t:'ما يراعى لحفص',narr:'هناك أحكام تراعى لمن يقرأ برواية حفص عن عاصم من طريق الشاطبية، وتؤخذ بالمشافهة. منها تسهيل الهمزة الثانية في أأعجمي، والإمالة في مجراها.',items:['تسهيل أأعجمي','إمالة مجراها']},
 {t:'السين والصاد والضعف',narr:'ينطق يبسط وبسطة بالسين، وبمصيطر بالصاد، والمصيطرون بالصاد وبالسين والمقدم الصاد. وفي كلمة ضعف في الروم الفتح هو المقدم، ويجوز الضم.',items:['يبسط، بسطة ← سين','بمصيطر ← صاد','ضعف ← فتح']}]});
(window.CH2=window.CH2||[]).push({id:'taa',n:16,t:'الوقف على تاء التأنيث',c:'#9d4edd',p:'ص ١٢٤-١٣٢',
 intro:'تاء التأنيث تُرسم في المصحف العثماني إما مربوطة (ة) فيوقف عليها بالهاء، وإما مفتوحة (ت) فيوقف عليها بالتاء اتباعاً للرسم.',
 secs:[
 {h:'القاعدة',b:'اتفقت المصاحف على رسم تاء التأنيث إذا كانت لاحقة بالأفعال بالتاء المفتوحة، ولا يوقف عليها إلا بالتاء، مثل ﴿وَقَالَتِ ٱلْيَهُودُ﴾ ﴿قَالَتْ طَّآئِفَةٌ﴾.<br>أما في الأسماء المفردة فالأصل أن ترسم بالتاء المربوطة ويوقف عليها بالهاء، مثل ﴿رَحْمَةٌ﴾ ﴿نِعْمَةً﴾.'},
 {h:'كلمات خرجت عن الأصل',b:'ثمة كلمات رُسمت بالتاء المفتوحة في الأسماء، فيوقف عليها بالتاء اتباعاً للرسم. وهي قسمان: ما اتفق القراء على قراءته بالإفراد، وما اختلفوا في إفراده وجمعه.'},
 {h:'القسم الأول: ثلاث عشرة كلمة (مفردة باتفاق)',b:'<b class=g>رحمت، نعمت، امرأت، سنت، لعنت، معصيت، كلمت، بقيت، قرت، فطرت، شجرت، جنت، ابنت</b>.'},
 {h:'رحمت (٧ مواضع)',b:'﴿يَرْجُونَ رَحْمَتَ ٱللَّهِ﴾ البقرة، ﴿إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ﴾ الأعراف، ﴿رَحْمَتُ ٱللَّهِ وَبَرَكَـٰتُهُۥ﴾ هود، ﴿ذِكْرُ رَحْمَتِ رَبِّكَ﴾ مريم، ﴿ءَاثَـٰرِ رَحْمَتِ ٱللَّهِ﴾ الروم، ﴿أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ﴾ الزخرف، ﴿وَرَحْمَتُ رَبِّكَ خَيْرٌ﴾ الزخرف. وما سوى ذلك مرسوم بالتاء المربوطة.'},
 {h:'نعمت (١١ موضعاً)',b:'مثل ﴿وَٱذْكُرُواْ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ﴾ ﴿وَإِن تَعُدُّواْ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ﴾ ﴿وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ﴾ ﴿فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ﴾. وما عدا ذلك بالتاء المربوطة مثل ﴿وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ﴾.'},
 {h:'امرأت (٧ مواضع)',b:'﴿إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ﴾ ﴿ٱمْرَأَتُ ٱلْعَزِيزِ﴾ (موضعان في يوسف) ﴿ٱمْرَأَتُ فِرْعَوْنَ﴾ القصص والتحريم، ﴿ٱمْرَأَتَ نُوحٍ﴾ ﴿ٱمْرَأَتَ لُوطٍ﴾. ويلاحظ أن (امرأة) إذا جاءت مضافة إلى زوجها رسمت بالتاء المفتوحة، وما عداها بالتاء المربوطة مثل ﴿وَإِنِ ٱمْرَأَةٌ خَافَتْ﴾.'},
 {h:'سنت (٥ مواضع)، لعنت (موضعان)',b:'﴿سُنَّتُ ٱلْأَوَّلِينَ﴾ الأنفال، ﴿سُنَّتَ ٱلْأَوَّلِينَ﴾ فاطر، ﴿لِسُنَّتِ ٱللَّهِ تَبْدِيلًا﴾ و﴿تَحْوِيلًا﴾ فاطر، ﴿سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ﴾ غافر. وما عداها بالمربوطة مثل ﴿سُنَّةَ مَن قَدْ أَرْسَلْنَا﴾.<br>﴿فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَـٰذِبِينَ﴾ آل عمران، ﴿أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ﴾ النور. وما عداهما بالمربوطة مثل ﴿لَعْنَةُ ٱللَّهِ﴾ البقرة.'},
 {h:'معصيت، كلمت، بقيت',b:'﴿وَمَعْصِيَتِ ٱلرَّسُولِ﴾ في موضعين في المجادلة وليس غيرهما.<br>﴿وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ﴾ الأعراف، بالتاء المفتوحة.<br>﴿بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ﴾ هود، وما عداه بالهاء مثل ﴿وَبَقِيَّةٌ مِّمَّا تَرَكَ﴾.'},
 {h:'قرت، فطرت، شجرت، جنت، ابنت',b:'﴿قُرَّتُ عَيْنٍ لِّى وَلَكَ﴾ القصص، وغيره بالهاء مثل ﴿قُرَّةَ أَعْيُنٍ﴾.<br>﴿فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا﴾ الروم، ولا ثاني له.<br>﴿إِنَّ شَجَرَتَ ٱلزَّقُّومِ﴾ الدخان، وغيره بالهاء مثل ﴿شَجَرَةِ ٱلْخُلْدِ﴾.<br>﴿وَجَنَّتُ نَعِيمٍ﴾ الواقعة، وغيره بالهاء مثل ﴿وَجَنَّةٍ عَرْضُهَا﴾.<br>﴿ٱبْنَتَ عِمْرَٰنَ﴾ التحريم، ولا ثاني له.'},
 {h:'القسم الثاني: سبع كلمات مختلف في إفرادها وجمعها (١٢ موضعاً)',b:'<b class=g>آيات، غيابت، بينات، ثمرات، جمالت، كلمت، الغرفات</b>. من المواضع: ﴿ءَايَـٰتٌ لِّلسَّآئِلِينَ﴾ يوسف، ﴿غَيَـٰبَتِ ٱلْجُبِّ﴾ يوسف، ﴿وَهُمْ فِى ٱلْغُرُفَـٰتِ ءَامِنُونَ﴾ سبأ، ﴿فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ﴾ فاطر، ﴿مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا﴾ فصلت، ﴿جِمَـٰلَتٌ صُفْرٌ﴾ المرسلات، ﴿وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا﴾ الأنعام. وقد رسمت بالتاء المفتوحة، والراجح كتابتهما والوقف عليهما بالتاء.'},
 {h:'كلمات أخرى تكتب وقفاً بالتاء',b:'﴿طَالُوتَ﴾ ﴿بِجَالُوتَ﴾ ﴿ٱلتَّابُوتُ﴾ ﴿بِٱلطَّـٰغُوتِ﴾ ﴿ذَاتِ﴾ ﴿مَرْضَاتِ﴾ ﴿وَلَاتَ حِينَ مَنَاصٍ﴾ ﴿هَيْهَاتَ﴾ ﴿ٱللَّاتَ﴾ ﴿يَـٰٓأَبَتِ﴾.'}],
 ayat:[{k:'3:35',hw:'امرأت عمران',lab:'امرأت مفتوحة التاء: الوقف بالتاء'},{k:'11:73',hw:'رحمت الله',lab:'رحمت: الوقف بالتاء'},{k:'30:30',hw:'فطرت الله',lab:'فطرت: الوقف بالتاء'},{k:'2:2',hw:'',lab:''}].slice(0,3),
 cards:[['كيف يوقف على الفعل اللاحق بتاء التأنيث؟','بالتاء المفتوحة دائماً.'],['كيف يوقف على الاسم المرسوم بالتاء المربوطة؟','بالهاء.'],['كيف يوقف على الاسم المرسوم بالتاء المفتوحة؟','بالتاء اتباعاً للرسم.'],['كم كلمة اتفق على إفرادها؟','ثلاث عشرة كلمة.'],['كلمات الاتفاق؟','رحمت، نعمت، امرأت، سنت، لعنت، معصيت، كلمت، بقيت، قرت، فطرت، شجرت، جنت، ابنت.'],['كم موضعاً لرحمت بالتاء؟','سبعة مواضع.'],['كم موضعاً لنعمت بالتاء؟','أحد عشر موضعاً.'],['متى ترسم امرأت بالتاء؟','إذا أضيفت إلى زوجها.'],['كم كلمة في القسم المختلف فيه؟','سبع كلمات في اثني عشر موضعاً.'],['كيف يوقف على «طالوت» و«ذات» و«هيهات»؟','بالتاء.']],
 quiz:[['الوقف على ﴿قَالَتْ﴾:',['بالهاء','بالتاء'],1,'الفعل يوقف عليه بالتاء.'],['الوقف على ﴿رَحْمَةٌ﴾ (مربوطة):',['بالهاء','بالتاء'],0,'التاء المربوطة يوقف عليها بالهاء.'],['الوقف على ﴿ٱمْرَأَتُ عِمْرَٰنَ﴾:',['بالهاء','بالتاء'],1,'مرسومة بالتاء.'],['الوقف على ﴿ٱلتَّابُوتُ﴾:',['بالتاء','بالهاء'],0,'مرسومة بالتاء.'],['﴿فِطْرَتَ ٱللَّهِ﴾ في الروم:',['وقف بالتاء','وقف بالهاء'],0,'مرسومة بالتاء المفتوحة.']],
 vid:[{t:'الوقف على تاء التأنيث',narr:'تاء التأنيث ترسم في المصحف إما مربوطة وإما مفتوحة. فإن كانت مربوطة وقفنا عليها بالهاء، مثل: رحمة. وإن كانت مفتوحة وقفنا عليها بالتاء اتباعاً للرسم.',items:['مربوطة ة ← وقف بالهاء','مفتوحة ت ← وقف بالتاء','الوقف تابع للرسم']},
 {t:'الأفعال وبعض الأسماء',narr:'والأفعال تكتب دائماً بالتاء المفتوحة، مثل: قالت. وقد خرجت كلمات من الأسماء فرسمت بالتاء المفتوحة، وهي ثلاث عشرة كلمة.',items:['الأفعال: قالت، وقفا بالتاء','١٣ كلمة في الأسماء']},
 {t:'الكلمات الثلاث عشرة',narr:'وهي: رحمت، ونعمت، وامرأت، وسنت، ولعنت، ومعصيت، وكلمت، وبقيت، وقرت، وفطرت، وشجرت، وجنت، وابنت. وتحفظ مواضعها.',items:['رحمت، نعمت، امرأت','سنت، لعنت، معصيت','كلمت، بقيت، قرت','فطرت، شجرت، جنت، ابنت']}]});
(window.CH2=window.CH2||[]).push({id:'waqf',n:12,t:'الوقف والابتداء',c:'#3a86ff',p:'ص ٨٧-٩٣',
 intro:'الوقف والابتداء من أهم مباحث التلاوة. يحتاج القارئ إلى معرفة موضع الوقف السليم، ثم الابتداء المستقيم.',
 secs:[
 {h:'التعريفات الأربعة',b:'<b class=g>الوقف:</b> قطع الصوت على آخر الكلمة زمناً يتنفس فيه القارئ عادة، بنية استئناف القراءة، لا بنية الإعراض عنها. ويكون على رؤوس الآيات وأواسطها، ولا يكون في وسط الكلمة.<br><b class=g>الابتداء:</b> الشروع في القراءة بعد قطع أو وقف.<br><b class=g>القطع:</b> قطع القراءة والانتهاء منها، كمن يقطع عند نهاية الحزب. ولا يكون إلا على رأس آية.<br><b class=g>السكت:</b> قطع الصوت زمناً أقصر من الوقف من غير تنفس، بنية العودة إلى القراءة في الحال.'},
 {h:'مواضع السكت لحفص (أربعة)',b:'١) على ألف ﴿عِوَجَاۜ﴾ في الكهف عند وصلها بـ﴿قَيِّمًا﴾.<br>٢) على ألف ﴿مَرْقَدِنَاۜ﴾ في يس حال وصلها بما بعدها.<br>٣) على نون ﴿مَنْۜ رَاقٍ﴾ في القيامة.<br>٤) على لام ﴿بَلْۜ رَانَ﴾ في المطففين.'},
 {h:'أقسام الوقف',b:'ثلاثة: <b class=g>اختياري</b>، و<b class=g>اختباري</b>، و<b class=g>اضطراري</b>.'},
 {h:'١ الوقف الاختياري',b:'يقصده القارئ بمحض اختياره، وهو المقصود من الوقف. ينبغي اختيار موضع مناسب للتنفس والاستراحة، بحيث لا يُخِلّ بالمعنى. وينقسم إلى أربعة أقسام: التام، والكافي، والحسن، والقبيح.'},
 {h:'الوقف التام',b:'هو الذي تم معناه ولم يتعلق بما بعده لا لفظاً ولا معنى. وأكثر ما يكون في رؤوس الآيات وانقضاء القصص. مثل الوقف على ﴿وَأُوْلَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ﴾. <b class=g>حكمه:</b> يحسن الوقف عليه ويحسن الابتداء بما بعده.'},
 {h:'الوقف الكافي',b:'هو الذي تم معناه وتعلق بما بعده في المعنى فقط لا في اللفظ. وهو أكثر الوقوف وقوعاً. مثل الوقف على ﴿وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ﴾. <b class=g>حكمه:</b> يحسن الوقف عليه والابتداء بما بعده.'},
 {h:'الوقف الحسن',b:'هو الذي تم معناه في ذاته، وتعلق بما بعده لفظاً ومعنى. مثل الوقف على ﴿بِسْمِ ٱللَّهِ﴾ و﴿ٱلْحَمْدُ لِلَّهِ﴾. <b class=g>حكمه:</b> يحسن الوقف عليه ولا يحسن الابتداء بما بعده، إلا إذا كان رأس آية فيحسن الوقف عليه، لأن الوقف على رؤوس الآي سنة.'},
 {h:'الوقف القبيح',b:'هو الوقف على ما لم يتم معناه لتعلقه بما بعده لفظاً ومعنى، أو أفاد معنى غير مقصود، أو أوهم فساد المعنى. مثل الوقف على ﴿ٱلْحَمْدُ﴾ من ﴿ٱلْحَمْدُ لِلَّهِ﴾ أو على ﴿لَا تَقْرَبُواْ ٱلصَّلَوٰةَ﴾. <b class=r>حكمه:</b> لا يجوز تعمده إلا لضرورة من ضيق نفس أو عطاس، ولا يجوز الابتداء بما بعده.'},
 {h:'٢ الوقف الاختباري',b:'هو الوقف الذي يكون عند سؤال مختبِر أو تعليم معلّم، كالوقف على كلمة مقطوعة أو موصولة في الرسم العثماني، لبيان موافقة الوقف للرسم. يجوز الوقف عليه عند السؤال أو التعليم.'},
 {h:'٣ الوقف الاضطراري',b:'هو الوقف الذي يعرض للقارئ بسبب ضرورة ألجأته إليه، كضيق النفس أو العطاس أو السعال أو النسيان. يجوز الوقف عليه للضرورة على أي كلمة، وبعد انقضاء الضرورة يبتدئ بالكلمة التي وقف عليها إن كان يصلح البدء بها، وإلا يبدأ بما قبلها.'},
 {h:'أنواع الابتداء',b:'لا يكون الابتداء إلا اختيارياً. وأقسامه كأقسام الوقف: <b class=g>التام</b> (بأول السورة أو القصة)، <b class=g>الكافي</b>، <b class=g>الحسن</b>، <b class=r>القبيح</b> (يُغيّر المعنى أو يفسده، مثل البدء بـ﴿ٱللَّهَ فَقِيرٌ﴾ أو ﴿ٱبْنُ ٱللَّهِ﴾).'}],
 ayat:[{k:'2:5',hw:'المفلحون',lab:'وقف تام على رأس الآية'},{k:'2:3',hw:'ينفقون',lab:'وقف كاف'},{k:'1:2',hw:'الحمد لله',lab:'الوقف على «لله» حسن، وعلى «الحمد» قبيح'},{k:'4:43',hw:'لا تقربوا',lab:'الوقف على ﴿لَا تَقْرَبُواْ ٱلصَّلَوٰةَ﴾ قبيح'}],
 cards:[['ما الوقف؟','قطع الصوت زمناً يتنفس فيه عادة بنية استئناف القراءة.'],['ما الابتداء؟','الشروع في القراءة بعد قطع أو وقف.'],['ما القطع؟','قطع القراءة والانتهاء منها، ولا يكون إلا على رأس آية.'],['ما السكت؟','قطع الصوت زمناً دون زمن الوقف من غير تنفس.'],['كم موضع سكت لحفص؟','أربعة: عوجا، مرقدنا، من راق، بل ران.'],['أقسام الوقف؟','اختياري، اختباري، اضطراري.'],['أقسام الوقف الاختياري؟','تام، كاف، حسن، قبيح.'],['ما الوقف التام؟','تم معناه ولا تعلق له بما بعده لفظاً ولا معنى.'],['ما الوقف الكافي؟','تعلقه بما بعده في المعنى فقط.'],['ما الوقف الحسن؟','تعلقه بما بعده لفظاً ومعنى.'],['ما الوقف القبيح؟','وقف على ما لم يتم معناه أو يوهم فساده.'],['متى يجوز الوقف القبيح؟','للضرورة فقط، كضيق النفس أو العطاس.']],
 quiz:[['الوقف على رأس الآية يكون:',['سنة','بدعة'],0,'الوقف على رؤوس الآي سنة.'],['كم موضع للسكت عند حفص؟',['٢','٤','٦'],1,'أربعة مواضع.'],['قطع الصوت دون تنفس بنية العودة:',['الوقف','السكت','القطع'],1,'هذا هو السكت.'],['الوقف الذي تعلق بما بعده في المعنى فقط:',['التام','الكافي','الحسن'],1,'هذا هو الكافي.'],['الوقف على ﴿ٱلْحَمْدُ﴾ من ﴿ٱلْحَمْدُ لِلَّهِ﴾:',['تام','حسن','قبيح'],2,'قبيح لأن المعنى لم يتم.'],['الوقف بسبب العطاس:',['اختياري','اضطراري','اختباري'],1,'هذا اضطراري.']],
 vid:[{t:'الوقف والابتداء',narr:'الوقف هو قطع الصوت على آخر الكلمة زمناً يتنفس فيه القارئ بنية استئناف القراءة. والابتداء هو الشروع في القراءة بعد قطع أو وقف. والسكت هو قطع الصوت دون تنفس.',items:['الوقف: قطع مع تنفس','الابتداء: الشروع بعد الوقف','السكت: قطع بلا تنفس']},
 {t:'مواضع السكت',narr:'ولحفص عن عاصم أربعة مواضع للسكت. على عوجا في الكهف. وعلى مرقدنا في يس. وعلى من راق في القيامة. وعلى بل ران في المطففين.',items:['عوجا ـ الكهف','مرقدنا ـ يس','من راق ـ القيامة','بل ران ـ المطففين']},
 {t:'أقسام الوقف',narr:'والوقف ثلاثة أقسام. اختياري، وهو الذي يقصده القارئ باختياره. واختباري، عند سؤال مختبر أو تعليم معلم. واضطراري، بسبب ضرورة كضيق النفس أو العطاس.',items:['اختياري','اختباري','اضطراري']},
 {t:'الوقف الاختياري',narr:'والاختياري أربعة أقسام. التام، وهو الذي لا تعلق له بما بعده. والكافي، وتعلقه بما بعده في المعنى فقط. والحسن، وتعلقه لفظاً ومعنى. والقبيح، وهو ما لم يتم معناه، فلا يجوز الوقف عليه إلا لضرورة.',items:['تام: لا تعلق','كاف: تعلق في المعنى','حسن: تعلق لفظاً ومعنى','قبيح: لا يجوز إلا لضرورة']}]});

